export type DependencyGraph = Readonly<Record<string, readonly string[]>>;

export function collectDependencies(
  graph: DependencyGraph,
  roots: readonly string[]
): string[] {
  const rootSet = new Set(roots);
  const visited = new Set<string>();
  const result: string[] = [];

  const visit = (symbol: string): void => {
    if (visited.has(symbol)) return;
    visited.add(symbol);
    if (!rootSet.has(symbol)) result.push(symbol);
    for (const dependency of graph[symbol] ?? []) visit(dependency);
  };

  for (const root of roots) {
    if (!visited.has(root)) visited.add(root);
    for (const dependency of graph[root] ?? []) visit(dependency);
  }

  return result;
}

