import { collectDependencies } from './solution';
import type { DependencyGraph } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  const left = JSON.stringify(actual);
  const right = JSON.stringify(expected);
  if (left !== right) throw new Error(`${message}: expected ${right}, got ${left}`);
}

const graph: DependencyGraph = {
  app: ['ui', 'core', 'ui'],
  ui: ['shared', 'theme'],
  shared: ['core', 'missing'],
  core: ['util'],
  util: ['core'],
  theme: [],
};
const graphBefore = JSON.stringify(graph);
const roots = ['app'];
const rootsBefore = JSON.stringify(roots);
equal(
  collectDependencies(graph, roots),
  ['ui', 'shared', 'core', 'util', 'missing', 'theme'],
  'transitive depth-first discovery order with cycles and duplicates',
);
equal(JSON.stringify(graph), graphBefore, 'graph and dependency arrays are not mutated');
equal(JSON.stringify(roots), rootsBefore, 'roots are not mutated');

equal(collectDependencies(graph, []), [], 'empty roots');
equal(collectDependencies(graph, ['unknown']), [], 'absent root is a leaf');
equal(collectDependencies({ leaf: [] }, ['leaf']), [], 'empty dependency list is a leaf');

const multipleRoots: DependencyGraph = {
  first: ['a', 'second', 'b'],
  a: ['deep'],
  deep: ['first'],
  second: ['c'],
  c: ['deep'],
  b: ['c'],
};
equal(
  collectDependencies(multipleRoots, ['first', 'second', 'first']),
  ['a', 'deep', 'c', 'b'],
  'roots are excluded but their dependencies remain traversable',
);

const emptyNames: DependencyGraph = {
  '': ['x', 'other'],
  x: ['', 'leaf'],
  other: [''],
};
equal(collectDependencies(emptyNames, ['', '']), ['x', 'leaf', 'other'], 'empty root name and duplicate roots');

const absentReferenced: DependencyGraph = { root: ['missing', 'missing', 'present'], present: ['missing'] };
equal(collectDependencies(absentReferenced, ['root']), ['missing', 'present'], 'absent referenced symbols are included once as leaves');

